    "helpTopicsTitle": "도움말 주제",
    "helpBasics": "기본 사항",
    "helpBasicsText": [
      "키보드의 Z-M 및 Q-U 행은 음을 입력합니다(배치에 관계없이 키 위치에 따라). 1은 노트 컷, 는 릴리스, 16진수는 악기, 볼륨 및 이펙트 열을 채웁니다.",
      "Space는 편집을 토글하고, Enter는 재생 또는 중지를 수행하며, F5~F8은 곡을 재생, 패턴 반복, 커서부터 재생, 중지를 실행합니다.",
      "선택 영역이 있으면 Edit 및 Pattern 메뉴에서 복사, 잘라내기, 붙여넣기, 보간, 역순, 전조 등 다양한 작업을 수행할 수 있습니다.",
      "패턴, 프레임, 북마크 등의 편집은 실행 취소(Ctrl+Z)가 가능하지만, 데스크톱과 마찬가지로 악기는 취소할 수 없습니다. 모듈은 작업 중 브라우저에 저장됩니다."
    ],
    "helpMouse": "마우스",
    "helpMouseText": [
      "클릭하면 커서가 셀에 위치하고 드래그하면 선택됩니다. 행 번호에서 드래그하면 전체 행이 선택되고, 더블 클릭하면 프레임이 선택되며, 셀을 더블 클릭하면 해당 채널이 선택됩니다. 오른쪽 버튼은 메뉴를 엽니다.",
      "휠은 행을 이동하며, Ctrl을 누르면 전조, Shift를 누르면 값 변경, 두 키를 누르면 프레임 단위로 이동합니다.",
      "프레임 목록은 드래그로도 선택할 수 있으며, 프레임을 자르기, 복사 및 붙여넣기 할 수 있습니다. 마우스 오른쪽 버튼을 클릭하면 프레임 메뉴가 열립니다."
    ],
    "helpKeys": "키",
