    "helpTopicsTitle": "Tópicos de Ajuda",
    "helpBasics": "O básico.",
    "helpBasicsText": [
      "As linhas Z-M e Q-U do teclado digitam notas (pelo lugar da chave, qualquer que seja o layout). 1 é um corte de nota, \\ uma liberação, os dígitos hexadecimais preenchem o instrumento, volume e colunas de efeito.",
      "Space Alterna a edição, Enter Toca ou para, F5 para F8 Toque a música, toque o padrão, toque do cursor e pare.",
      "Com uma seleção, os menus Editar e Padrão copiam, cortam e colam, interpolam, revertem, transponham e muito mais.",
      "Edições de padrões, quadros, favoritos e assim por diante podem ser desfeitas ( Ctrl +Z); instrumentos, como na área de trabalho, não podem."
    ],
    "helpMouse": "O rato.",
    "helpMouseText": [
      "Um clique coloca o cursor em uma célula e um arrastar seleciona. No número da linha, um arrastar seleciona linhas inteiras e um duplo clique no quadro; um duplo clique em uma célula seleciona seu canal. O botão direito abre um menu.",
      "A roda move as fileiras; com Ctrl transpõe, com Shift altera os valores, com ambos vai de quadro em quadro.",
      "A lista de quadros seleciona arrastando também, e corta, copia e cola quadros."
    ],
    "helpKeys": "Chaves.",
    "helpKeysText": "O navegador mantém algumas chaves ( Ctrl + F4 , Ctrl + W ...), que uma página não pode obter.",
