      "fdsBias": "Zxx - Automatique FDS biais du taux de modulation; XX - 80 = compensation",
      "phaseReset": "=00 - Phase de réinitialisation du canal",
      "harmonic": "Kxx - Multiplier la fréquence par XX; n'affecte pas Ixy Automatique FDS modulation",
      "targetVolume": "Nxy - Diapositive du volume cible; X = vitesse; Y = volume"
