    "helpTopicsTitle": "Sujets d'aide",
    "helpBasics": "Les bases",
    "helpBasicsText": [
      "Les lignes Z-M et Q-U du clavier entrent les notes (par la place de la clé, quelle que soit la mise en page). 1 est une coupure de note, \\ une libération, les chiffres hexagonaux remplissent l'instrument, le volume et les colonnes d'effet.",
      "Space l'édition des toggles, Enter joue ou s'arrête, F5 à F8 jouer la chanson, boucler le motif, jouer à partir du curseur et s'arrêter.",
      "Avec une sélection, les menus Édition et Pattern copient, découpent et collent, interpolent, inversent, transposent et plus encore.",
      "Les modifications de motifs, d'images, de signets, etc. peuvent être annulées ( Ctrl +Z); les instruments, comme sur le bureau, ne peuvent pas. Le module est conservé dans ce navigateur au fur et à mesure que vous travaillez."
    ],
    "helpMouse": "La souris",
    "helpMouseText": [
      "Un clic met le curseur sur une cellule et un glisser sélectionne. Sur les numéros de ligne, un glisser sélectionne des lignes entières et un double clic sur le cadre; un double clic sur une cellule sélectionne son canal. Le bouton droit ouvre un menu.",
      "La roue déplace les lignes ; avec Ctrl elle transpose, avec Shift elle change les valeurs, avec les deux elle va du cadre au cadre.",
      "La liste des cadres sélectionne aussi en faisant glisser, et découpe, copie et colle les cadres. Son bouton droit ouvre le menu des cadres."
    ],
    "helpKeys": "Clés",
    "helpKeysText": "Configuration > Les touches les changent. Le navigateur conserve quelques touches ( Ctrl + F4 , Ctrl +W...), qu'une page ne peut pas obtenir.",
