    "helpTopicsTitle": "Helfen Sie Themen",
    "helpBasics": "Die Grundlagen",
    "helpBasicsText": [
      "Die Z-M- und Q-U-Zeilen der Tastatur geben Notizen ein (nach der Stelle der Taste, unabhängig vom Layout). 1 ist ein Notizschnitt, \\ eine Freigabe, die Hex-Ziffern füllen die Instrumenten-, Volumen- und Effektspalten.",
      "Space schaltet die Bearbeitung um, Enter spielt oder stoppt, F5 bis F8 spielt das Lied, schlingt das Muster, spielt vom Cursor und stoppt.",
      "Mit einer Auswahl kopieren, schneiden und fügen die Menüs Edit und Pattern, interpolieren, reversieren, transponieren und mehr.",
      "Bearbeitungen von Mustern, Frames, Lesezeichen usw. können rückgängig gemacht werden ( Ctrl + Z); Instrumente, wie auf dem Desktop, können nicht."
    ],
    "helpMouse": "Die Maus",
    "helpMouseText": [
      "Ein Klick setzt den Cursor auf eine Zelle und ein Drag wählt. Auf den Zeilennummern wählt ein Drag ganze Zeilen und ein Doppelklick auf den Rahmen; ein Doppelklick auf eine Zelle wählt ihren Kanal. Der rechte Button öffnet ein Menü.",
      "Das Rad bewegt die Reihen; mit Ctrl transponiert es, mit Shift ändert es die Werte, mit beiden geht es von Rahmen zu Rahmen.",
      "Die Frame-Liste wählt durch Ziehen aus und schneidet, kopiert und fügt Frames ein. Die rechte Taste öffnet das Frame-Menü."
    ],
    "helpKeys": "Schlüssel",
    "helpKeysText": "Konfiguration > Schlüssel ändert sie. Der Browser behält einige Schlüssel ( Ctrl + F4 , Ctrl + W ...), die eine Seite nicht erhalten kann.",
    "effectTableTitle": "Wirkungstabelle",
    "effectTableIntro": "Geben Sie einen Effekt in die Effektspalte eines Musters ein: seinen Buchstaben und zwei hexadezimale Ziffern (xx oder x und y). Welche Chips einen Effekt annehmen, hängt vom Modul ab.",
    "effectColumn": "Wirkung",
    "effectName": "Name",
    "effectDescription": "Was es tut",
    "effectChips": "Chips",
    "allChips": "Alle",
    "effectInfo": {
      "1": [
        "Geschwindigkeit/Tempo",
        "xx unter dem Split-Punkt zwischen den beiden (32 standardmäßig) setzt die Geschwindigkeit, die Ticks einer Zeile; von ihm nach oben, das Tempo."
      ],
      "2": [
        "Sprung",
        "Springen Sie zum Frame xx."
      ],
      "3": [
        "Skip",
        "Fahren Sie mit Zeile xx des nächsten Frames fort."
      ],
      "4": [
        "Halt",
        "Hör auf zu spielen."
      ],
      "5": [
        "Längenzähler/Hüllkurve",
        "2A03 : 00-1F stellt den Längenzähler ein. E0-E3 schaltet den Hardware-Umschlag um."
      ],
      "6": [
        "Automatisches Portamento",
        "Slide zu jeder neuen Note mit Geschwindigkeit xx. 00 schaltet es aus."
      ],
      "8": [
        "Hardware-Sweep",
        "Der 2A03 -Impuls-Sweep. x ist die Geschwindigkeit, y der Betrag."
      ],
      "9": [
        "Hardware Sweep Down",
        "Der 2A03 -Impuls-Sweep. x ist die Geschwindigkeit, y der Betrag."
      ],
      "10": [
        "Arpeggio",
        "Spielen Sie die Note, dann +x und +y Halbtöne, jeweils ein Tick."
      ],
      "11": [
        "Vibrato",
        "x ist die Geschwindigkeit, y die Tiefe."
      ],
      "12": [
        "Tremolon",
        "x ist die Geschwindigkeit, y die Tiefe."
      ],
      "13": [
        "Feine Pitch",
        "Stellen Sie die Tonhöhe ein wenig ein. 80 ist die Mitte."
      ],
      "14": [
        "Anmerkungsverzögerung",
        "Spielen Sie die Note xx tickt spät."
      ],
      "15": [
        "DAC-Einstellung",
        "Setzen Sie den DPCM Delta-Zähler auf xx (00-7F)."
      ],
      "16": [
        "Portamento nach oben",
        "Erhöhen Sie den Pitch um xx jeden Tick."
      ],
      "17": [
        "Portamento nach unten",
        "Senken Sie die Tonhöhe um xx jeden Tick."
      ],
      "18": [
        "Arbeitszyklus",
        "2A03 -Impuls: 00-03 Rauschen: 00 und 01 (der Modus); andere Chips: ihre eigenen Arbeitszyklen."
      ],
      "19": [
        "Probenversatz",
        "Starten Sie das DPCM -Sample beim xx mal 64. Byte."
      ],
      "20": [
        "Notizrutsche nach oben",
        "x ist die Geschwindigkeit, y die Halbtöne um nach oben zu gehen."
      ],
      "21": [
        "Notrutsche nach unten",
        "x ist die Geschwindigkeit, y die Halbtöne, um nach unten zu gehen."
      ],
      "22": [
        "Volumenschieber",
        "Bei jedem Tick erhöhen Sie das Volumen um x und senken Sie es um y."
      ],
      "23": [
        "Note abschneiden",
        "Schneiden Sie die Notiz nach xx Ticks (00-7F)."
      ],
      "24": [
        "Retrigger",
        "Spielen Sie die DPCM Probe wieder alle xx tickt. 00 für keine."
      ],
      "25": [
        "Verzögertes Volumen",
        "Setzen Sie nach x Ticks das Kanalvolumen auf y."
      ],
      "26": [
        "Modulationstiefe",
        "Die FDS -Modulationstiefe (00-3F)."
      ],
      "27": [
        "Modulationsgeschwindigkeit hoch",
        "Das hohe Byte der FDS -Modulationsgeschwindigkeit (00-0F) ab 10 ist es das Verhältnis der automatischen Modulation."
      ],
      "28": [
        "Modulationsgeschwindigkeit niedrig",
        "Das niedrige Byte der FDS -Modulationsgeschwindigkeit."
      ],
      "29": [
        "DPCM Stellplatz",
        "Wie schnell der DPCM spielt (00-0F)."
      ],
      "30": [
        "Hüllform",
        "Der Sunsoft 5B Umschlag. y ist die Form (0-F), x der automatische Umschlagwechsel. 00 schaltet ihn aus."
      ],
      "31": [
        "Hüllperiode hoch",
        "Das hohe Byte der Sunsoft 5B Umschlagperiode."
      ],
      "32": [
        "Einhüllende Periode niedrig",
        "Das niedrige Byte der Sunsoft 5B Umschlagperiode."
      ],
      "33": [
        "Lärmperiode",
        "Die Sunsoft 5B Rauschperiode (00-1F)."
      ],
      "34": [
        "Benutzerdefinierter Patch-Port",
        "Wählen Sie das Register (0-7) des VRC7 benutzerdefinierten Patches zum Schreiben."
      ],
      "35": [
        "Custom Patch Write",
        "Schreiben Sie xx in das Register Hxx , das vom VRC7 benutzerdefinierten Patch ausgewählt wurde."
      ],
      "36": [
        "Verzögerte Freigabe",
        "Geben Sie die Notiz nach xx Ticks (00-7F) frei."
      ],
      "37": [
        "Groove",
        "Verwenden Sie groove xx."
      ],
      "38": [
        "Verzögerte Umsetzung",
        "Die niedrigen 3 Bits von x sind die Ticks zu warten, sein oberes Bit die Richtung (1 ist nach unten), y die Halbtöne."
      ],
      "39": [
        "Wellenpuffer",
        "Setzen Sie die N163 -Welle bei xx mal 2. 7F geht zurück auf das Instrument."
      ],
      "40": [
        "Volumenumschlag",
        "Der FDS -Volumenumschlag. 00-7F stellt Rate und Modus ein, E0 schaltet ihn aus."
      ],
      "41": [
        "Modulation Bias",
        "Der FDS automatische FM-Bias. 80 ist die Mitte."
      ],
      "42": [
        "Phase Reset",
        "Setzen Sie die Phase der Welle zurück, ohne die Note erneut zu spielen."
      ],
      "43": [
        "Harmonisch",
        "Multiplizieren Sie die Tonhöhe mit xx."
      ],
      "44": [
        "Zielvolumenrutsche",
        "x ist die Geschwindigkeit, y das Volumen zu erreichen. 00 stoppt es."
      ]
    },
