    "helpTopicsTitle": "Помогите темам",
    "helpBasics": "Основы",
    "helpBasicsText": [
      "Ряды Z-M и Q-U клавиатуры вводят ноты (по месту клавиши, независимо от компоновки). 1 - это вырезанная нота, \\ выпуск, шестизначные цифры заполняют столбцы инструмента, объема и эффекта.",
      "Space редактирование переключателей, Enter воспроизведение или остановка, F5 до F8 воспроизведение песни, цикл шаблона, воспроизведение с курсора и остановка.",
      "С помощью выбора меню Edit и Pattern копируют, вырезают и вставляют его, интерполируют, реверсируют, транспонируют и многое другое.",
      "Редактирование шаблонов, рамок, закладок и так далее может быть отменено ( Ctrl + Z); инструменты, как на рабочем столе, не могут.Модуль хранится в этом браузере по мере работы."
    ],
    "helpMouse": "Мышь",
    "helpMouseText": [
      "Клик ставит курсор на ячейку и выбирает перетаскивание. На номерах строк перетаскивание выбирает целые строки и двойной щелчок кадра; двойной щелчок на ячейке выбирает ее канал. Правая кнопка открывает меню.",
      "Колесо перемещает ряды; с Ctrl оно переносит, с Shift оно меняет значения, причем оба оно переходит от рамы к раме.",
      "Список кадров также выбирает перетаскивание и вырезает, копирует и вставляет кадры. Его правая кнопка открывает меню кадров."
    ],
